// The iframe is part of the initial HTML. Keep its browsing context in place
// when filling in the report so the first roll also survives on older Safari.
function renderReportPage(app, markup) {
  const hero = app.querySelector('[data-board-shell]');
  if (!hero) {
    app.innerHTML = markup;
    return;
  }
  const template = document.createElement('template');
  template.innerHTML = markup;
  const full = template.content;
  app.querySelector('header').replaceWith(full.querySelector('header'));
  const fullHero = full.querySelector('main > .hero');
  hero.querySelector('.hero-copy').replaceWith(fullHero.querySelector('.hero-copy'));
  const opening = hero.closest('[data-zone="opening"]');
  const main = opening.parentNode;
  let afterHero = false;
  for (const child of Array.from(full.querySelector('main').children)) {
    if (child === fullHero) afterHero = true;
    else if (afterHero) main.append(child);
    else main.insertBefore(child, opening);
  }
  hero.removeAttribute('data-board-shell');
}

